using Indamin.Performance.Data;using Indamin.Performance.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace Indamin.Performance.Controllers;
[Authorize(Policy="AdminOnly")]public class ReportsController(AppDbContext db,ExcelService excel):Controller{
public async Task<IActionResult>Index(int? periodId){var p=periodId??await db.Periods.OrderByDescending(x=>x.StartAt).Select(x=>(int?)x.Id).FirstOrDefaultAsync()??0;ViewBag.Periods=await db.Periods.OrderByDescending(x=>x.StartAt).ToListAsync();ViewBag.PeriodId=p;return View(await Query(p));}
[HttpGet]public async Task<IActionResult>Export(int? periodId){var p=periodId??await db.Periods.OrderByDescending(x=>x.StartAt).Select(x=>(int?)x.Id).FirstOrDefaultAsync()??0;return File(excel.Evaluations((await Query(p)).Select(x=>(x.Employee,x.Evaluator,x.Unit,x.Position,x.Score,x.Max,x.Status))),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","EvaluationReport.xlsx");}
private Task<List<Row>>Query(int id)=>db.Evaluations.AsNoTracking().Where(x=>x.PeriodId==id).Join(db.Employees,ev=>ev.EmployeeId,e=>e.Id,(ev,e)=>new{ev,e}).Join(db.Employees,z=>z.ev.EvaluatorId,a=>a.Id,(z,a)=>new{z.ev,z.e,z.a}).Join(db.OrgUnits,z=>z.e.UnitId,u=>u.Id,(z,u)=>new{z.ev,z.e,z.a,z.u}).Join(db.Positions,z=>z.e.PositionId,p=>p.Id,(z,p)=>new Row(z.e.FullName,z.a.FullName,z.u.Title,p.Title,z.ev.FinalScore,z.ev.FinalMaxScore,z.ev.Status.ToString())).ToListAsync();
public record Row(string Employee,string Evaluator,string Unit,string Position,decimal Score,decimal Max,string Status);
}